.mg-panel{font:13px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;color:var(--od-text,#1b2c49);padding:16px 12px;min-width:0}
.mg-panel *{box-sizing:border-box}.mg-panel [hidden]{display:none!important}
.mg-setting-row{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:48px}
.mg-setting-copy{min-width:0}.mg-setting-copy label{font-size:13px;font-weight:650;display:block}
.mg-note{margin:4px 0 0;color:var(--od-text-secondary,#5b6e86);font-size:12px;line-height:1.55}
.mg-switch{appearance:none;-webkit-appearance:none;flex:none;position:relative;width:38px;height:36px;margin:0;border:0;background:transparent;cursor:pointer}
.mg-switch:before{content:"";position:absolute;inset:7px 0;width:38px;height:22px;border-radius:999px;background:#7f8da1;transition:background .12s ease}
.mg-switch:after{content:"";position:absolute;top:9px;left:2px;width:18px;height:18px;border-radius:50%;background:#fff;transition:transform .12s ease}
.mg-switch:checked:before{background:var(--od-brand,#365eda)}.mg-switch:checked:after{transform:translateX(16px)}
.mg-switch:disabled{opacity:.52;cursor:not-allowed}.mg-switch:focus-visible{outline:2px solid var(--od-brand,#365eda);outline-offset:3px}
.mg-section-head{padding-top:16px;margin-top:16px;margin-bottom:12px;border-top:1px solid var(--od-border,#dfe6ef)}
.mg-section-head h2{margin:0;font-size:12px;font-weight:650}
.mg-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin:0;padding:0;list-style:none;min-width:0;border:1px solid var(--od-border,#dfe6ef);border-radius:12px;overflow:hidden}
.mg-item{display:flex;align-items:center;gap:8px;min-width:0;padding:12px;font-size:13px}
.mg-arrow{display:grid;place-items:center;flex:none;width:26px;height:26px;border-radius:6px;background:var(--od-bg-muted,#f5f7fb);color:var(--od-brand,#365eda);font-size:19px;font-weight:700}
.mg-hint{margin:16px 0 0;color:var(--od-text-secondary,#5b6e86);font-size:12px}
.mg-error{margin:12px 0 0;color:var(--od-danger,#b42318);font-size:12px;line-height:1.55}
@media(max-width:260px){.mg-item{padding:8px;gap:6px}}
@media(prefers-reduced-motion:reduce){.mg-switch:before,.mg-switch:after{transition:none}}

